mapper.select:
select d.post_id postId, p.post_name postName, p.post_type postType, d.is_default isDefault from sys_dept_post d join sys_post p on d.post_id = p.post_id where dept_id = #{query.deptId} and p.tenant_id = #{tenantId}
and p.post_name like concat('%', #{query.postName}, '%')
and p.post_type = #{query.postType}
order by p.post_type

with pids as (select post_id from sys_post except select post_id from sys_dept_post where dept_id = #{query.deptId}) select p.post_id postId, p.post_name postName, p.post_type postType from pids join sys_post p on pids.post_id = p.post_id where p.tenant_id = #{tenantId}
and p.post_name like concat('%', #{query.postName}, '%')
and p.post_type = #{query.postType}
order by p.post_type

mapper.insert:
insert into sys_dept_post(dept_id, post_id, is_default) select t.dept_id, t.post_id, t.is_default from (
select #{item.deptId} as dept_id, #{item.postId} as post_id, #{item.isDefault} as is_default
) t where exists (select 1 from sys_dept where sys_dept.dept_id = t.dept_id and sys_dept.tenant_id = #{tenantId}) on duplicate key update is_default = values(is_default)

mapper.select:
select dept_id, post_id, is_default from sys_dept_post where (dept_id, post_id) in (
(#{item.deptId}, #{item.postId})
)
